mapper.update:
update ts_catalog_snapshot
status = #{status}, storage_uri = #{storageUri}, quality_report = #{qualityReport}, update_time = sysdate()
where snapshot_id = #{snapshotId}

update ts_catalog_snapshot set status = 'RETIRED', update_time = sysdate()
where library_id = #{libraryId} and status = 'ACTIVE'
and snapshot_id <> #{exceptId}
